// Browser stand-in for Node built-ins used by kordoc (generated by scripts/gen-node-shims.mjs).
// Functions kordoc only needs on a file system (CLI, OCR, native image tools) throw when called.
const fail=(n)=>()=>{throw new Error(n+" is not available in the browser")};
export const createCipheriv=fail("createCipheriv");
export const createDecipheriv=fail("createDecipheriv");
export const createHash=fail("createHash");
export const pbkdf2Sync=fail("pbkdf2Sync");
export const randomUUID=()=>globalThis.crypto.randomUUID();
export const timingSafeEqual=fail("timingSafeEqual");
export default {createCipheriv,createDecipheriv,createHash,pbkdf2Sync,randomUUID,timingSafeEqual};
